namespace Blackjackas
{
    static class HandFont
    {
        public static readonly int[][] Widths;
        public static readonly ulong[][][] Rows;

        static HandFont()
        {
            Widths = new int[65][];
            Rows = new ulong[65][][];
            byte[] raw = System.Convert.FromBase64String(string.Concat(Data));
            int at = 0;
            for (int height = 4; height <= 64; height++)
            {
                Widths[height] = new int[10];
                Rows[height] = new ulong[10][];
                for (int digit = 0; digit < 10; digit++)
                {
                    int width = raw[at++];
                    Widths[height][digit] = width;
                    int count = (width + 7) / 8;
                    var rows = new ulong[height];
                    for (int y = 0; y < height; y++)
                    {
                        ulong value = 0;
                        for (int b = 0; b < count; b++)
                        {
                            value |= (ulong)raw[at++] << (8 * b);
                        }
                        rows[y] = value;
                    }
                    Rows[height][digit] = rows;
                }
            }
        }

        public static int Bit(int height, int digit, int y, int x)
        {
            return (int)((Rows[height][digit][y] >> x) & 1ul);
        }

